import{c as o,Q as r,j as n,m as s}from"./chunks/framework.rWdQudnF.js";const u=JSON.parse('{"title":"架构师-备考 综合知识-数据库-关系数据库与SQL","description":"","frontmatter":{"title":"架构师-备考 综合知识-数据库-关系数据库与SQL"},"headers":[],"relativePath":"综合知识/数据库/关系数据库与SQL.md","filePath":"综合知识/数据库/关系数据库与SQL.md","lastUpdated":null}'),l={name:"综合知识/数据库/关系数据库与SQL.md"};function e(g,t,i,d,a,c){return r(),n("div",null,[...t[0]||(t[0]=[s('<h3 id="数据库三级模式-两级映像" tabindex="-1">数据库三级模式-两级映像 <a class="header-anchor" href="#数据库三级模式-两级映像" aria-label="Permalink to &quot;数据库三级模式-两级映像&quot;">​</a></h3><p><strong>三级模式层级：</strong></p><ul><li><strong>内模式</strong>（Internal Schema）：描述数据的物理存储结构与存取方式，直接关联存储设备上的数据文件。</li><li><strong>概念模式</strong>（Conceptual Schema，简称&quot;模式&quot;）：定义数据的逻辑结构与关系，体现为数据库中的基本表，是全局数据的抽象表示。</li><li><strong>外模式</strong>（External Schema）：呈现用户视角的数据组织形式，通过视图、部分表等机制实现，是概念模式的逻辑子集。</li></ul><p><strong>两级映像机制：</strong></p><ul><li><strong>外模式-概念模式映像</strong>：建立外模式与概念模式间的映射关系。当概念模式结构变更（如表结构调整）时，仅需调整此映像即可保持外模式不变，实现<strong>逻辑数据独立性</strong>。</li><li><strong>概念模式-内模式映像</strong>：定义概念模式与物理存储的映射规则。当存储结构变更（如文件组织方式修改）时，通过调整此映像可维持概念模式不变，实现<strong>物理数据独立性</strong>。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/Pasted%20image%2020230830100737.png" alt="三级模式两级映像"></p><blockquote><p><strong>核心优势</strong>：两级映像机制有效隔离应用程序与底层数据，确保物理独立性（存储优化不影响应用逻辑）和逻辑独立性（数据结构演进不强制修改程序）。</p></blockquote><hr><h3 id="关系数据库基本术语" tabindex="-1">关系数据库基本术语 <a class="header-anchor" href="#关系数据库基本术语" aria-label="Permalink to &quot;关系数据库基本术语&quot;">​</a></h3><p><strong>键体系：</strong></p><ul><li><strong>超键</strong>：能唯一标识此表的属性的组合。</li><li><strong>候选键</strong>：超键中去掉冗余的属性，剩余的属性就是候选键。</li><li><strong>主键</strong>：任选一个候选键，即可作为主键。</li><li><strong>外键</strong>：其他表中的主键。</li><li><strong>主属性</strong>：候选键内的属性为主属性，其他属性为非主属性。</li></ul><p><strong>完整性约束：</strong></p><ul><li><strong>实体完整性约束</strong>：即主键约束，主键值不能为空，也不能重复。</li><li><strong>参照完整性约束</strong>：即外键约束，外键必须是其他表中已经存在的主键的值，或者为空。</li><li><strong>用户自定义完整性约束</strong>：自定义表达式约束，如设定年龄属性的值必须在 0 到 150 之间。</li></ul><hr><h3 id="关系代数" tabindex="-1">关系代数 <a class="header-anchor" href="#关系代数" aria-label="Permalink to &quot;关系代数&quot;">​</a></h3><p><strong>基本运算：</strong></p><ul><li><strong>并（∪）</strong>：两张表中所有记录数合并，相同记录只显示一次。</li><li><strong>交（∩）</strong>：两张表中相同的记录。</li><li><strong>差（−）</strong>：S1 − S2，结果是 S1 表中有而 S2 表中没有的那些记录。</li><li><strong>笛卡尔积（×）</strong>：S1 × S2，产生的结果包括 S1 和 S2 的所有属性列，S1 中每条记录依次和 S2 中所有记录组合，属性列 = S1+S2，记录数 = S1×S2。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/Pasted%20image%2020230830114025.png" alt="并交差笛卡尔积示意"></p><p><strong>投影（π）与选择（σ）：</strong></p><ul><li><strong>投影</strong>：按条件选择某关系模式中的<strong>某列</strong>（垂直分割），列也可以用数字表示。相当于 SQL 的 <code>SELECT</code> 指定列。</li><li><strong>选择</strong>：按条件选择某关系模式中的<strong>某条记录</strong>（水平分割）。相当于 SQL 的 <code>WHERE</code> 条件。</li></ul><blockquote><p>口诀：<strong>投影选列，选择选行</strong>。</p></blockquote><p><strong>自然连接（⋈）：</strong></p><p>结果显示全部的属性列，但<strong>相同属性列只显示一次</strong>，显示两个关系模式中属性相同且值相同的记录。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/Pasted%20image%2020230830171537.png" alt="自然连接示例"></p><p><strong>关系代数表达式对应关系：</strong></p><ul><li>投影 <code>π</code> → SQL SELECT 指定列</li><li>选择 <code>σ</code> → SQL WHERE 条件</li><li>笛卡尔积 <code>×</code> → FROM 多表（逗号分隔）</li><li>自然连接 <code>⋈</code> → 自动匹配同名列（去重列）</li></ul><blockquote><p><strong>经典考题</strong>：自然连接 <code>R ⋈ S</code> 与笛卡尔积 <code>R × S</code> 的等价转换</p><ul><li>自然连接列数 = R列数 + S列数 − 相同列数</li><li>笛卡尔积列数 = R列数 + S列数</li><li>等价条件需要加上投影 π（去重列）和选择 σ（同名列值相等）</li></ul></blockquote><hr><h3 id="元组关系演算" tabindex="-1">元组关系演算 <a class="header-anchor" href="#元组关系演算" aria-label="Permalink to &quot;元组关系演算&quot;">​</a></h3><ul><li><strong>定义</strong>：一种非过程化的查询语言，用于描述从数据库中检索哪些元组，而<strong>不指定如何检索</strong>。</li><li><strong>表达式形式</strong>：<code>{ t | P(t) }</code>，其中 <code>t</code> 是元组变量，<code>P(t)</code> 是一个谓词（条件）。</li><li><strong>存在量词 <code>∃</code></strong>：表示&quot;存在&quot;，只要存在一个元组使条件成立，<code>t</code> 就会被选中。</li><li><strong>全称量词 <code>∀</code></strong>：表示&quot;所有&quot;。</li><li><strong>属性引用</strong>：通过位置（索引）引用，如 <code>t[3]</code> 表示元组 <code>t</code> 的第三个属性。</li></ul><blockquote><p><strong>解题技巧</strong>：遍历关系中每个元组，检查是否存在（<code>∃</code>）或是否所有（<code>∀</code>）满足条件，按位置索引比较属性值。</p></blockquote><hr><h3 id="函数依赖" tabindex="-1">函数依赖 <a class="header-anchor" href="#函数依赖" aria-label="Permalink to &quot;函数依赖&quot;">​</a></h3><p><strong>基本概念：</strong></p><p>给定一个 X，能唯一确定一个 Y，就称 X 函数确定 Y，或者说 Y 函数依赖于 X，记作 <strong>X → Y</strong>。</p><p><strong>依赖分类：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>定义</th><th>示例</th></tr></thead><tbody><tr><td><strong>完全函数依赖</strong></td><td>X → Y，且 X 的任何真子集都不能确定 Y</td><td>(A,B) → C，A↛C，B↛C</td></tr><tr><td><strong>部分函数依赖</strong></td><td>X → Y，但 X 的真子集也能确定 Y</td><td>(A,B) → C，且 A → C</td></tr><tr><td><strong>传递函数依赖</strong></td><td>X → Y，Y → Z，且 Y↛X（X 和 Y 不等价）</td><td>A → B，B → C，B↛A</td></tr></tbody></table><p><strong>Armstrong 公理系统：</strong></p><ol><li><strong>自反律</strong>（Reflexivity）：如果 Y ⊆ X ⊆ U，则 X → Y 成立（平凡依赖）。</li><li><strong>增广律</strong>（Augmentation）：如果 X → Y 成立，且 Z ⊆ U，则 XZ → YZ 成立。</li><li><strong>传递律</strong>（Transitivity）：如果 X → Y 和 Y → Z 成立，则 X → Z 成立。</li></ol><p><strong>推导规则：</strong></p><ul><li><strong>合并规则</strong>：X → Y 且 X → Z ⇒ X → YZ</li><li><strong>伪传递规则</strong>：X → Y 且 WY → Z ⇒ XW → Z</li><li><strong>分解规则</strong>：X → Y 且 Z ⊆ Y ⇒ X → Z</li></ul><blockquote><p><strong>找候选键技巧</strong>：找出<strong>从未在右边出现过的属性</strong>，必然是候选键之一，以该属性为基础，根据依赖集依次扩展，看能否遍历所有属性，将无法遍历的加入候选键中。</p></blockquote><hr><h3 id="范式-1nf-2nf-3nf-bcnf" tabindex="-1">范式（1NF / 2NF / 3NF / BCNF） <a class="header-anchor" href="#范式-1nf-2nf-3nf-bcnf" aria-label="Permalink to &quot;范式（1NF / 2NF / 3NF / BCNF）&quot;">​</a></h3><p><strong>第一范式（1NF）：</strong> 关系中的每一个分量必须是一个不可分的数据项。即<strong>表中不允许有小表</strong>。</p><p><strong>第二范式（2NF）：</strong> 在 1NF 基础上，每一个<strong>非主属性完全函数依赖于任何一个候选码</strong>。即非主属性不能依赖复合主键中的某一个列（消除部分函数依赖）。</p><p><strong>第三范式（3NF）：</strong> 在 2NF 基础上，表中<strong>不存在非主属性对码的传递依赖</strong>。</p><p><strong>BC 范式（BCNF）：</strong> 在 3NF 基础上进一步<strong>消除主属性对于码的部分函数依赖和传递依赖</strong>。通俗地说：<strong>每一个依赖的左边决定因素都必然包含候选键</strong>。</p><p><strong>范式递进关系：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1NF ⊃ 2NF ⊃ 3NF ⊃ BCNF</span></span></code></pre></div><p>每次升级解决上一级的问题：</p><ul><li>1NF → 2NF：消除<strong>部分函数依赖</strong></li><li>2NF → 3NF：消除<strong>传递函数依赖</strong></li><li>3NF → BCNF：消除<strong>主属性对码的部分和传递依赖</strong></li></ul><p><strong>实例演算：</strong></p><p>学生表（学号，学生姓名，系编号，系名，系主任，课程号，成绩）</p><ul><li>候选键：(学号, 课程号)</li><li><strong>1NF 问题</strong>：不满足 2NF，因为学号不能完全确定课程号和成绩</li><li><strong>分解到 2NF</strong>：学生(学号, 姓名, 系编号, 系名, 系主任) + 选课(学号, 课程号, 成绩)</li><li><strong>2NF 问题</strong>：学生表中 学号→系编号→系主任，存在传递依赖</li><li><strong>分解到 3NF</strong>：学生(学号, 姓名, 系编号) + 系(系编号, 系名, 系主任) + 选课(学号, 课程号, 成绩)</li></ul><hr><h3 id="模式分解" tabindex="-1">模式分解 <a class="header-anchor" href="#模式分解" aria-label="Permalink to &quot;模式分解&quot;">​</a></h3><p><strong>目的</strong>：解决关系模式中存在的数据冗余、插入异常、删除异常和更新异常问题，通过投影运算将低范式转换为高范式关系集合。</p><h4 id="保持函数依赖" tabindex="-1">保持函数依赖 <a class="header-anchor" href="#保持函数依赖" aria-label="Permalink to &quot;保持函数依赖&quot;">​</a></h4><blockquote><p><strong>定义</strong>：分解后的多个关系模式，保持原来的依赖集不变。注意要消除掉冗余依赖（如传递依赖）。</p></blockquote><p><strong>判断方法：</strong></p><ol><li><strong>快速判断法</strong>（充分条件）：如果 F 上的每一个函数依赖都在其分解后的某一个关系上成立（左右两边属性都在同一个分解模式中），则这个分解是保持依赖的。</li><li><strong>闭包方法</strong>：当分解后的子关系模式不能直接包含某个函数依赖时，使用闭包计算验证。</li></ol><h4 id="无损分解" tabindex="-1">无损分解 <a class="header-anchor" href="#无损分解" aria-label="Permalink to &quot;无损分解&quot;">​</a></h4><blockquote><p><strong>定义</strong>：将分解后的子关系进行自然连接后，能完全恢复出原关系的所有数据，没有任何信息丢失或产生多余的元组。</p></blockquote><p><strong>定理（二分解判定）</strong>：将 R 分解为 {R1, R2} 是无损的<strong>充要条件</strong>是： <code>R1 ∩ R2 → (R1 − R2)</code> 或 <code>R1 ∩ R2 → (R2 − R1)</code> 在 F⁺ 中成立。</p><blockquote><p>口诀：<strong>交决定差</strong>。</p></blockquote><p><strong>表格法（通用判定）</strong>：</p><ol><li>画表格：行是子模式 Rᵢ，列是所有属性</li><li>子模式中含有的属性填 <code>✓</code>，否则填 <code>×</code></li><li>根据函数依赖修改表格：若依赖左边属性值相同，则右边属性也强制相同（优先将 × 改为 ✓）</li><li>若最终<strong>存在某一行全部为 <code>✓</code></strong>，则为无损分解</li></ol><blockquote><p><strong>经典结论</strong>：模式分解中，<strong>无损分解不一定保持函数依赖，保持函数依赖也不一定是无损的</strong>。两者需分别判断。</p></blockquote><hr><h3 id="e-r-模型与概念结构设计" tabindex="-1">E-R 模型与概念结构设计 <a class="header-anchor" href="#e-r-模型与概念结构设计" aria-label="Permalink to &quot;E-R 模型与概念结构设计&quot;">​</a></h3><p><strong>数据模型三要素：</strong></p><ul><li><strong>数据结构</strong>：所研究的对象类型的集合</li><li><strong>数据操作</strong>：对数据库中各种对象的实例允许执行的操作的集合</li><li><strong>数据的约束条件</strong>：一组完整性规则的集合</li></ul><p><strong>E-R 图基本元素：</strong></p><ul><li><strong>椭圆</strong>表示属性</li><li><strong>长方形</strong>表示实体</li><li><strong>菱形</strong>表示联系（连线两端填写联系类型）</li></ul><p><strong>联系类型</strong>：一对一（1:1）、一对多（1:N）、多对多（M:N）</p><p><strong>弱实体与强实体</strong>：弱实体依赖于强实体的存在而存在（如&quot;家长&quot;依赖于&quot;学生&quot;）。</p><p><strong>E-R 模型 → 关系模型转换规则：</strong></p><ul><li>每个实体对应一个关系模式</li><li><strong>1:1 联系</strong>：可放到任意一端实体中作为属性，或单独成为一个关系模式</li><li><strong>1:N 联系</strong>：在 N 端加入 1 端实体的主键，或单独成为一个关系模式</li><li><strong>M:N 联系</strong>：<strong>必须</strong>作为一个单独的关系模式，主键是 M 和 N 端的联合主键</li></ul><p><strong>E-R 图集成三大冲突：</strong></p><table tabindex="0"><thead><tr><th>冲突类型</th><th>定义</th><th>示例</th></tr></thead><tbody><tr><td><strong>属性冲突</strong></td><td>同一属性在不同局部图中定义不一致</td><td>类型冲突（整数 vs 字符串）、取值域冲突（{男,女} vs {M,F}）</td></tr><tr><td><strong>命名冲突</strong></td><td>同名异义或异名同义</td><td>&quot;单位&quot;既指部门又指计量单位</td></tr><tr><td><strong>结构冲突</strong></td><td>同一对象被抽象为不同的模型成分</td><td>同一对象在一图中是实体，另一图中是属性</td></tr></tbody></table><hr><h3 id="数据库设计步骤" tabindex="-1">数据库设计步骤 <a class="header-anchor" href="#数据库设计步骤" aria-label="Permalink to &quot;数据库设计步骤&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>产出物</th></tr></thead><tbody><tr><td>1. <strong>需求分析</strong></td><td>分析数据存储要求</td><td>数据流图、数据字典、需求说明书</td></tr><tr><td>2. <strong>概念结构设计</strong></td><td>设计 E-R 图（分 E-R 图→合并 E-R 图）</td><td>E-R 图</td></tr><tr><td>3. <strong>逻辑结构设计</strong></td><td>E-R 图转换为关系模式</td><td>关系模式、完整性约束、用户视图</td></tr><tr><td>4. <strong>物理设计</strong></td><td>确定数据分布、存储结构和访问方式</td><td>物理存储方案</td></tr><tr><td>5. <strong>数据库实施</strong></td><td>建立数据库、编制与调试应用程序</td><td>可运行的数据库</td></tr><tr><td>6. <strong>运行和维护</strong></td><td>评价、调整与修改</td><td>持续维护</td></tr></tbody></table><blockquote><p><strong>关键题点</strong>：逻辑结构设计阶段的依据来自<strong>需求分析</strong>阶段的产物（需求说明文档、数据字典、数据流图）。</p></blockquote><hr><h3 id="sql-语言基础" tabindex="-1">SQL 语言基础 <a class="header-anchor" href="#sql-语言基础" aria-label="Permalink to &quot;SQL 语言基础&quot;">​</a></h3><p><strong>DDL（数据定义语言）：</strong></p><ul><li><code>CREATE TABLE</code> — 创建表</li><li><code>ALTER TABLE</code> — 修改表</li><li><code>DROP TABLE</code> — 删除表</li><li><code>PRIMARY KEY()</code> — 指定主键</li><li><code>FOREIGN KEY()</code> — 指定外键</li><li><code>CREATE INDEX</code> / <code>CREATE VIEW</code> — 创建索引/视图</li></ul><p><strong>DML（数据操作语言）：</strong></p><ul><li><code>SELECT ... FROM ... WHERE</code> — 查询</li><li><code>INSERT INTO ... VALUES()</code> — 插入</li><li><code>DELETE FROM ... WHERE</code> — 删除</li><li><code>UPDATE ... SET ... WHERE</code> — 修改</li></ul><p><strong>常用语法：</strong></p><ul><li><code>GROUP BY</code> — 分组查询，<code>HAVING</code> 附加分组条件</li><li><code>ORDER BY</code> — 排序（默认升序 ASC，降序 DESC）</li><li><code>AS</code> — 更名运算：<code>SELECT sno AS &quot;学号&quot; FROM t1</code></li><li><code>LIKE</code> — 字符串匹配：<code>%</code> 匹配多个字符，<code>_</code> 匹配一个字符</li><li><code>DISTINCT</code> — 过滤重复，只保留一条</li><li><code>UNION</code> — 取或运算（去重合并）</li><li><code>INTERSECT</code> — 取与运算（交集）</li><li>聚合函数：<code>MIN</code>、<code>AVG</code>、<code>MAX</code>、<code>COUNT</code>、<code>SUM</code></li></ul>',93)])])}const h=o(l,[["render",e]]);export{u as __pageData,h as default};
